// Build the in-memory database dataset from the canonical v2 rules corpus.
//
// The Astro pages import this at build time and pass the resulting rows into
// the pure `filterDatabaseRows` helper. The corpus is generated by the
// pipeline (src/generators/v2.ts) and shipped as a static JSON artifact, so the
// website stays hostable on any static CDN without a server-side resolver.

import type { DatabaseRow } from './database-state.ts';

interface CorpusRule {
  id: string;
  conceptId: string;
  categoryId?: string;
  validFrom: string;
  validToExclusive: string | null;
  rate?:
    | { type: 'percentage'; value: string }
    | { type: 'fixed'; amount: string; currency: string }
    | { type: 'specific'; amount: string; unit: string; currency?: string }
    | { type: 'progressive'; brackets: { upTo: string | null; rate: string }[] }
    | { type: 'formula'; expression: string }
    | { type: 'range'; min: string; max: string }
    | { type: 'free_text'; text: string }
    | { type: 'zero' }
    | { type: 'not_applicable' }
    | { type: 'information_factor'; factor: string };
  conditions?: unknown;
  verification?: { status: string; sourceIds: string[]; evidence?: unknown[] };
  exclusiveGroup?: string;
  supersedes?: string[];
  supersededBy?: string[];
  notes?: string;
}

interface CorpusConcept {
  id: string;
  categoryId: string;
  name: string;
  slug?: string;
  description?: string;
}

interface CorpusCategory {
  id: string;
  name: string;
  slug: string;
  description?: string;
}

interface CorpusConflict {
  id: string;
  ruleIds: string[];
}

interface RulesCorpus {
  data: {
    rules: CorpusRule[];
    concepts: CorpusConcept[];
    categories: CorpusCategory[];
    conflicts: CorpusConflict[];
  };
}

/** Format a v2 Rate into the compact string shown in the table. */
export function formatRate(rate: CorpusRule['rate']): string {
  if (!rate) return '—';
  switch (rate.type) {
    case 'percentage': {
      const n = Number(rate.value);
      return Number.isFinite(n) ? `${(n * 100).toLocaleString('id-ID', { maximumFractionDigits: 2 })}%` : `${rate.value}`;
    }
    case 'zero':
      return '0%';
    case 'fixed':
      return `${rate.currency} ${rate.amount}`;
    case 'specific':
      return `${rate.currency ?? ''}${rate.amount}/${rate.unit}`.trim();
    case 'range': {
      const a = Number(rate.min) * 100;
      const b = Number(rate.max) * 100;
      return `${a}%–${b}%`;
    }
    case 'progressive': {
      const rates = rate.brackets.map((b) => Number(b.rate) * 100);
      if (rates.length === 0) return 'Progresif';
      if (rates.length > 8) return `${Math.min(...rates)}%–${Math.max(...rates)}%`;
      return rates.map((r) => `${r}%`).join('/');
    }
    case 'formula':
      return 'Formula';
    case 'information_factor':
      return `Faktor ${rate.factor}`;
    case 'free_text':
      return rate.text;
    case 'not_applicable':
      return 'N/A';
    default:
      return '—';
  }
}

export interface DatabaseDataset {
  rows: DatabaseRow[];
  categories: { slug: string; name: string; count: number }[];
  conflictCount: number;
  release: { generatedAt?: string; sourceHash?: string; version?: string };
}

/**
 * Build the dataset from a parsed rules corpus. Pure: same input -> same rows,
 * sorted by id so two builds never disagree on order. Categories are returned
 * with their visible row counts so the toolbar can render accurate counters.
 *
 * `superseded` is populated from the v2 corpus `supersededBy` relation so the
 * Task 9 Mn2 status derivation can distinguish `diubah` (superseded but
 * visible) from `dicabut` (revoked with no declared successor).
 */
export function buildDatabaseDataset(corpus: RulesCorpus): DatabaseDataset {
  const { rules, concepts, categories, conflicts } = corpus.data;

  const conceptById = new Map(concepts.map((c) => [c.id, c]));
  const categoryById = new Map(categories.map((c) => [c.id, c]));
  const conflictRuleIds = new Set(conflicts.flatMap((c) => c.ruleIds));

  const rows: DatabaseRow[] = rules.map((rule) => {
    const concept = conceptById.get(rule.conceptId);
    const category = rule.categoryId ? categoryById.get(rule.categoryId) : undefined;
    const slug = category?.slug ?? concept?.slug ?? rule.conceptId;
    return {
      id: concept?.id ?? rule.id,
      ruleId: rule.id,
      category: slug,
      name: concept?.name ?? rule.id,
      rate: formatRate(rule.rate),
      validFrom: rule.validFrom,
      validToExclusive: rule.validToExclusive ?? null,
      verification: rule.verification?.status ?? 'summary_only',
      conflict: conflictRuleIds.has(rule.id),
      superseded: Array.isArray(rule.supersededBy) && rule.supersededBy.length > 0,
    };
  });

  // Stable input order for the pure filter: id-ascending then validFrom.
  rows.sort((a, b) => a.id.localeCompare(b.id) || a.validFrom.localeCompare(b.validFrom));

  const categoryCounts = new Map<string, number>();
  for (const row of rows) categoryCounts.set(row.category, (categoryCounts.get(row.category) ?? 0) + 1);
  const categoryList = categories
    .filter((c) => c.slug !== 'illustrative')
    .map((c) => ({ slug: c.slug, name: c.name, count: categoryCounts.get(c.slug) ?? 0 }));

  return {
    rows,
    categories: categoryList,
    conflictCount: conflicts.length,
    release: {
      generatedAt: (corpus as { release?: { generatedAt?: string; sourceHash?: string; version?: string } }).release?.generatedAt,
      sourceHash: (corpus as { release?: { sourceHash?: string } }).release?.sourceHash,
      version: (corpus as { release?: { version?: string } }).release?.version,
    },
  };
}
